	// Delete emergency alerts
	
	function delete_emergency_alert(){
		$.ajax({
			url: "index.php?quietmode=1&display=dashboard&module=pms&command=delete_emergency_alert&checked=Ok",
			dataType:"json",
			success: function (json) {
				window.location.reload();
			}
		});			
	};	

